try {
  const DELAY = 300;
  const SUBMIT = `#__next [data-testid='SummaryCoupon'] button`;
  const COUPON = `#__next input[name='coupon-pc']`

  const EVENTS = 
  [new Event('input', { bubbles: true }), 
  new Event('change'), 
  new Event('blur'), 
  new Event('focus')];
  
  EVENTS.forEach(EVENT => { 
    document.querySelector(COUPON).dispatchEvent(EVENT); 
  });
  
  setTimeout(() => {
    document.querySelector(SUBMIT).click();
  },DELAY)
}catch(e){}

